const rawStdout = $input.first().json.stdout || '';

let meta;
try {
  meta = JSON.parse(rawStdout);
} catch (e) {
  throw new Error('Pa11y stdout ist kein gültiges JSON: ' + e.message);
}

if (!meta.path) {
  throw new Error('Pa11y-Runner hat keinen Pfad zurückgegeben.');
}

return {
  path: meta.path,
  size: meta.size,
  source: meta.source || 'pa11y',
  url: $('Pa11y').first().json.url
};

// input: { exitCode, stderr, stdout, url? }
const meta = JSON.parse($input.first().json.stdout || '{}');
return {
  path: meta.path,
  size: meta.size,
  source: meta.source,
  url: $('axe').first().json.url
};

// Build Report (GAA) - Version für aggregierte Daten

const input = $input.first().json || {};

// URL aus Manager-Agent holen, Fallback: input.url
let managerData = {};
try {
  managerData = $('Manager-Agent').first().json || {};
} catch (e) {
  managerData = {};
}

let url = 'unbekannte URL';
const urlCandidates = [
  input.url,
  managerData.url,
];

for (const c of urlCandidates) {
  if (typeof c === 'string' && c.trim()) {
    url = c.trim();
    break;
  }
}

// NEU: Zugriff auf die aggregierten Ergebnisse aus dem vorherigen Node
const aggregatedResults = Array.isArray(input.aggregatedResults) ? input.aggregatedResults : [];
const stats = input.stats || { total_issues: 0, critical: 0, serious: 0 };

// Ergebnis berechnen
let result = 'pass';
if (stats.critical > 0 || stats.serious > 0) {
  result = 'fail';
} else if (stats.total_issues > 0) {
  result = 'warning';
}

// Kurzfassung generieren
let summary;
if (result === 'pass') {
  summary =
    'In den ausgewerteten Ergebnissen von axe-core und Pa11y wurden keine ' +
    'kritischen oder schweren Findings identifiziert, die auf Probleme bei ' +
    'der Erfüllung von WCAG 2.5.8 (Target Size – Minimum) hindeuten.';
} else {
  summary =
    `Es wurden ${stats.total_issues} Findings identifiziert, davon ${stats.critical} kritisch und ${stats.serious} schwerwiegend.`;
}

// Markdown-Report bauen (dynamisch aus den aggregierten Gruppen)
const lines = [];

lines.push('## Zusammenfassung');
lines.push(summary, '');
lines.push('## Detaillierte Findings (Aggregiert)', '');

if (aggregatedResults.length === 0) {
  lines.push('- Keine relevanten Fehler gefunden.', '');
} else {
  aggregatedResults.forEach((issue, index) => {
    // Titelzeile: [CRITICAL] ID (Anzahl)
    const icon = issue.impact === 'critical' ? '🔴' : (issue.impact === 'serious' ? '🟠' : '⚪');
    const title = `### ${index + 1}. ${icon} [${issue.impact.toUpperCase()}] ${issue.id} (${issue.count}x)`;

    lines.push(title);
    lines.push(`- **Tool:** ${issue.tool}`);
    lines.push(`- **Beschreibung:** ${issue.description}`);

    lines.push(`- **Betroffene Elemente (Auszug):**`);
    issue.selectors.forEach(sel => {
       // Code-Block für Selektoren, damit Sonderzeichen nicht Markdown kaputt machen
       lines.push(`  - \`${sel}\``);
    });

    if (issue.count > 5) {
        lines.push(`  - ... und ${issue.count - 5} weitere.`);
    }
    lines.push(''); // Leerzeile
  });
}

const reportMarkdown = lines.join('\n');

// Output für den Manager und PDF-Node
return [
  {
    json: {
      agent: 'GAA',
      url,
      wcag: ['2.5.8'],
      result,
      summary,
      // Wir geben die aggregierten Details weiter, damit der Manager sie nutzen kann
      details: {
        stats: stats,
        findings: aggregatedResults
      },
      reportMarkdown,
    },
  },
];

const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

// --- Hilfsfunktionen ---
function sanitize(text) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/\u202F/g, ' ');
  // Bereinigung von nicht-druckbaren Zeichen
  t = t.split('').map(ch => (ch.charCodeAt(0) > 255 ? ' ' : ch)).join('');
  return t;
}

function cleanInline(text) {
  if (!text) return '';
  // Entfernt Markdown-Syntax wie **fett** oder `code` für das PDF
  return text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1');
}

async function run() {
  const item = items[0];
  const data = item.json || {};
  const binary = item.binary || {};

  // 1. Daten aus dem JSON mappen
  const url = sanitize(data.url || 'unbekannte URL');
  const agentName = "GAA";
  const timestamp = new Date().toISOString().slice(0, 19).replace('T', ' ');

  // WICHTIG: Zugriff auf die verschachtelten Statistiken
  const stats = data.details?.stats || { total_issues: 0, critical: 0 };

  // WICHTIG: Wir nutzen den fertigen Markdown-Text aus dem vorherigen Node
  const md = sanitize(data.reportMarkdown || '');

  // PDF Setup
  const pdfDoc = await PDFDocument.create();
  let page = pdfDoc.addPage();
  let { width, height } = page.getSize();

  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let cursorY = height - 40;

  // --- Layout Helper ---
  function ensureSpace(linesNeeded, fontSize = 11) {
    if (cursorY - (linesNeeded * (fontSize + 4)) < 40) {
      page = pdfDoc.addPage();
      cursorY = height - 40;
    }
  }

  function drawTextLine(text, opts = {}) {
    const size = opts.size || 11;
    const font = opts.font || fontRegular;
    const color = opts.color || rgb(0, 0, 0);
    const indent = opts.indent || 40;
    const maxWidth = width - indent - 40;

    const words = text.split(' ');
    let line = '';

    for (const w of words) {
      const testLine = line ? line + ' ' + w : w;
      const wWidth = font.widthOfTextAtSize(testLine, size);
      if (wWidth > maxWidth) {
        ensureSpace(1, size);
        page.drawText(line, { x: indent, y: cursorY, size, font, color });
        cursorY -= (size + 4);
        line = w;
      } else {
        line = testLine;
      }
    }
    if (line) {
      ensureSpace(1, size);
      page.drawText(line, { x: indent, y: cursorY, size, font, color });
      cursorY -= (size + 4);
    }
  }

  // --- PDF Header ---

  // Titel
  page.drawText(`${agentName} Report`, { x: 40, y: cursorY, size: 18, font: fontBold });
  cursorY -= 30;

  // Metadaten
  drawTextLine(`URL: ${url}`);
  drawTextLine(`Zeitstempel: ${timestamp}`);

  // Stats Zeile (Rot wenn Fehler)
  const statsColor = stats.total_issues > 0 ? rgb(0.8, 0, 0) : rgb(0, 0.5, 0);
  drawTextLine(`Gesamte Fehler: ${stats.total_issues} (Kritisch: ${stats.critical})`, { 
      font: fontBold, 
      color: statsColor 
  });
  cursorY -= 20;

  // --- PDF Body (aus Markdown) ---

  const lines = md.split(/\r?\n/);

  for (const rawLine of lines) {
    let line = rawLine.trimEnd();
    if (!line.trim()) {
        cursorY -= 6;
        continue;
    }

    // Überschriften (###)
    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
        const text = cleanInline(headingMatch[2]);
        ensureSpace(2, 12);

        // Farbe für "CRITICAL" im Titel
        let color = rgb(0, 0, 0);
        if (text.includes('CRITICAL') || text.includes('🔴')) color = rgb(0.8, 0, 0);

        drawTextLine(text, { font: fontBold, size: 12, color });
        cursorY -= 4;
        continue;
    }

    // Listenpunkte
    const listMatch = line.match(/^\s*[-*]\s+(.*)$/);
    if (listMatch) {
        const text = cleanInline(listMatch[1]);
        drawTextLine('• ' + text, { indent: 55, size: 10 });
        continue;
    }

    // Normaler Text
    drawTextLine(cleanInline(line));
  }

  // PDF speichern
  const pdfBytes = await pdfDoc.save();
  const pdfBase64 = Buffer.from(pdfBytes).toString('base64');

  return [
    {
      json: data,
      binary: {
        report: {
          data: pdfBase64,
          mimeType: 'application/pdf',
          fileName: 'gaa-agent-report.pdf',
        },
        ...(binary.screenshot ? { screenshot: binary.screenshot } : {}),
      },
    },
  ];
}

return run();

const inputItem = $input.first().json;

// Daten holen (Fallback auf leere Objekte)
const axeInput = inputItem['axe-data'] || {};
const pa11yInput = inputItem['pa11y-data'] || {};

const url = axeInput.url || pa11yInput.url || 'unbekannte URL';

const axeViolations = axeInput.result?.violations || [];

const groupedIssues = {};

function addIssue(tool, id, description, impact, selector) {
  const key = `${tool}::${id}`;

  if (!groupedIssues[key]) {
    groupedIssues[key] = {
      tool: tool,
      id: id,
      description: description,
      impact: impact,
      count: 0,
      selectors: []
    };
  }

  groupedIssues[key].count++;
  if (groupedIssues[key].selectors.length < 5) {
    groupedIssues[key].selectors.push(selector);
  }
}

axeViolations.forEach(v => {

  v.nodes.forEach(node => {
    const selector = node.target && node.target.length > 0 ? node.target.join(' ') : 'unknown';
    addIssue('axe-core', v.id, v.help || v.description, v.impact, selector);
  });
});

const pa11yIssues = pa11yInput.issues || [];

pa11yIssues.forEach(issue => {

  let impact = 'minor';
  if (issue.type === 'error') impact = 'critical';
  if (issue.type === 'warning') impact = 'moderate';

  addIssue('pa11y', issue.code, issue.message, impact, issue.selector);
});

const resultsArray = Object.values(groupedIssues);

// Sortier-Reihenfolge definieren
const impactOrder = { 'critical': 0, 'serious': 1, 'moderate': 2, 'minor': 3, 'info': 4 };

resultsArray.sort((a, b) => {
  // Erst nach Schweregrad
  const orderA = impactOrder[a.impact] ?? 99;
  const orderB = impactOrder[b.impact] ?? 99;
  if (orderA !== orderB) return orderA - orderB;

  // Dann nach Anzahl (häufigste zuerst)
  return b.count - a.count;
});

// --- 4. Output für den Report ---
return {
  url: url,
  timestamp: new Date().toISOString(),
  agentName: "GAA_v1",
  // Wir geben jetzt die gruppierte Liste weiter, das spart massiv Platz
  aggregatedResults: resultsArray,
  stats: {
    total_issues: resultsArray.reduce((sum, item) => sum + item.count, 0),
    critical: resultsArray.filter(i => i.impact === 'critical').length,
    serious: resultsArray.filter(i => i.impact === 'serious').length
  }
};

const raw = $input.first();

// Falls der Agent einen String-Fehler zurückgibt
if (typeof raw === 'string') {
  return [{ json: { error: raw, agent: 'GAA', status: 'error' } }];
}

// Falls es ein Item ist, aber kein json-Feld hat
if (!raw.json) {
  return [{ json: { error: 'Agent returned no data', agent: 'GAA', status: 'error' } }];
}

// Alles OK → durchreichen
return [raw];
